\documentclass[tikz,border=8pt]{standalone}
\usepackage{amsmath}
\usetikzlibrary{calc}

\begin{document}

\begin{tikzpicture}[scale=1.35, >=stealth]

\pgfmathsetmacro{\k}{0.75}

\pgfmathsetmacro{\A}{1/4 + \k*\k/3}
\pgfmathsetmacro{\B}{2*\k*\k/3}
\pgfmathsetmacro{\C}{\k*\k/3 - 1}
\pgfmathsetmacro{\D}{\B*\B - 4*\A*\C}

\pgfmathsetmacro{\xQ}{(-\B - sqrt(\D))/(2*\A)}
\pgfmathsetmacro{\yQ}{\k*(\xQ + 1)}
\pgfmathsetmacro{\xP}{(-\B + sqrt(\D))/(2*\A)}
\pgfmathsetmacro{\yP}{\k*(\xP + 1)}

\pgfmathsetmacro{\xR}{-\xP}
\pgfmathsetmacro{\yR}{-\yP}

\coordinate (O) at (0,0);
\coordinate (F) at (-1,0);
\coordinate (P) at (\xP,\yP);
\coordinate (Q) at (\xQ,\yQ);
\coordinate (R) at (\xR,\yR);

\draw[->] (-2.5,0) -- (2.6,0) node[right] {$x$};
\draw[->] (0,-2.1) -- (0,2.2) node[above] {$y$};

\draw[thick] (0,0) ellipse [x radius=2, y radius=1.732];

\draw[thick, blue] ($(Q)!-0.12!(P)$) -- ($(P)!-0.12!(Q)$) node[above right] {$l$};
\draw[thick, dashed, orange] (P) -- (R);

\fill (O) circle (1.3pt) node[below right] {$O$};
\fill (F) circle (1.3pt) node[above left] {$F(-1,0)$};
\fill (P) circle (1.5pt) node[above right] {$P$};
\fill (Q) circle (1.5pt) node[below left] {$Q$};
\fill (R) circle (1.5pt) node[below right] {$R$};

\node at (1.15,1.95) {$C:\dfrac{x^2}{4}+\dfrac{y^2}{3}=1$};

\end{tikzpicture}

\end{document}
